using System;using System.Linq;using System.Collections.Generic;using UnityEngine;
public static class InspectComboSteps{
public static object Run(){var names=new[]{"Attack 05 - Skill_03","Attack 02 - Charged_Upward_Slash","Attack 03 - Double_Combo_Attack","Attack 06 - Weapon_Combo_1","Attack 05 - Skill_03","Attack 04 - Right_Hand_Sword_Slash","Attack 01 - Attack"};int[] starts={0,21,0,4,0,8,15},ends={16,42,41,39,16,22,33};var report=new List<object>();for(int i=0;i<names.Length;i++){var root=UnityEngine.Object.Instantiate(GameObject.Find(names[i]));try{root.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);var a=root.GetComponentInChildren<Animator>();a.enabled=false;var clip=a.runtimeAnimatorController.animationClips[0];foreach(int frame in new[]{starts[i],ends[i]}){clip.SampleAnimation(a.gameObject,frame/30f);var bones=root.GetComponentsInChildren<Transform>();var l=bones.First(t=>t.name=="LeftFoot");var r=bones.First(t=>t.name=="RightFoot");var h=bones.First(t=>t.name=="Hips");report.Add(new{segment=i+1,name=names[i],frame,left=l.position.ToString("F3"),right=r.position.ToString("F3"),hips=h.position.ToString("F3"),lead=l.position.z>r.position.z?"Left":"Right",difference=l.position.z-r.position.z});}}finally{UnityEngine.Object.DestroyImmediate(root);}}return report;}}
